ctx.loganalyzer.remove('search_text');
ctx.loganalyzer.remove('search_values');

def pending = new ArrayList();
def values = new ArrayList();

for (def entry : ctx.entrySet()) {
    if (!entry.getKey().startsWith('_') && entry.getKey() != '@version') {
        pending.add(entry.getValue());
    }
}

while (!pending.isEmpty()) {
    def value = pending.remove(pending.size() - 1);

    if (value instanceof Map) {
        for (def child : value.values()) {
            pending.add(child);
        }
    } else if (value instanceof List) {
        for (def child : value) {
            pending.add(child);
        }
    } else if (value != null) {
        values.add(value.toString());
    }
}

ctx.loganalyzer.search_text = values;
ctx.loganalyzer.search_values = values;
